-- IAM database only. Generated by EF Core 8.0.11 (idempotent, baseline -> AddUserOtpsTable).
-- Preflight added: do not apply this delta to a database missing the required baseline.
START TRANSACTION;
SET LOCAL search_path TO public;
DO $preflight$
BEGIN
    IF to_regclass('public."__EFMigrationsHistory"') IS NULL THEN
        RAISE EXCEPTION 'IAM migration history is missing. Select the IAM database and apply its baseline first.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."__EFMigrationsHistory"
        WHERE migration_id = '20261021100000_CounterReceiptPermissions') THEN
        RAISE EXCEPTION 'IAM baseline 20261021100000_CounterReceiptPermissions is required before this script.';
    END IF;
END $preflight$;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261022063951_AddUserOtpsTable') THEN
        IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'iam') THEN
            CREATE SCHEMA iam;
        END IF;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261022063951_AddUserOtpsTable') THEN
    CREATE TABLE iam.user_otps (
        id uuid NOT NULL,
        user_id uuid NOT NULL,
        otp_hash character varying(64) NOT NULL,
        channel character varying(10) NOT NULL,
        purpose character varying(30) NOT NULL,
        expires_at_utc timestamp with time zone NOT NULL,
        attempts integer NOT NULL,
        is_used boolean NOT NULL,
        created_at_utc timestamp with time zone NOT NULL,
        CONSTRAINT pk_user_otps PRIMARY KEY (id),
        CONSTRAINT ck_user_otps_attempts CHECK (attempts BETWEEN 0 AND 5),
        CONSTRAINT ck_user_otps_channel CHECK (channel IN ('EMAIL','SMS')),
        CONSTRAINT ck_user_otps_purpose CHECK (purpose IN ('CHANGE_PASSWORD','FORGOT_PASSWORD')),
        CONSTRAINT fk_user_otps_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261022063951_AddUserOtpsTable') THEN
    CREATE TABLE iam.welcome_emails (
        id uuid NOT NULL,
        user_id uuid NOT NULL,
        attempts integer NOT NULL,
        next_attempt_at_utc timestamp with time zone NOT NULL,
        sent_at_utc timestamp with time zone,
        CONSTRAINT pk_welcome_emails PRIMARY KEY (id),
        CONSTRAINT fk_welcome_emails_users_user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261022063951_AddUserOtpsTable') THEN
    CREATE INDEX ix_user_otps_user_id_created_at_utc ON iam.user_otps (user_id, created_at_utc);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261022063951_AddUserOtpsTable') THEN
    CREATE INDEX ix_welcome_emails_sent_at_utc_next_attempt_at_utc ON iam.welcome_emails (sent_at_utc, next_attempt_at_utc);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261022063951_AddUserOtpsTable') THEN
    CREATE UNIQUE INDEX ix_welcome_emails_user_id ON iam.welcome_emails (user_id);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "migration_id" = '20261022063951_AddUserOtpsTable') THEN
    INSERT INTO "__EFMigrationsHistory" (migration_id, product_version)
    VALUES ('20261022063951_AddUserOtpsTable', '8.0.11');
    END IF;
END $EF$;
COMMIT;

